      "Վիեննայի Շտրաուս ֆիլհարմոնիկ նվագախումբը դեկտեմբերի 3-ին և 4-ին Երևանում է՝ Սպենդիարյանի անվան օպերայի և բալետի թատրոնում, «Վիեննական վալս» ծրագրով. տոմսերը՝ 15000-ից 35000 դրամ։",
