      "URU-ն ձևավորվել է ԹՈՒՄՈ-ում՝ Արիկ Գրիգորյանի երաժշտական աշխատարանում։ Խմբում չորս առաջատար վոկալիստ են և ծանր ռիթմ-սեկցիա, իսկ հնչողությունը կառուցված է երազկոտ մեղեդիների և ծանր ռիթմերի վրա։",
